'use strict';
/* Pesito a Pesito — offline-first personal finance PWA. Money is integer cents. */
const DATA_KEY='pesito-a-pesito-v01', UI_KEY='pesito-ui-v04';
const GROUPS=['Everyday Money','Savings','Retirement','Debts'];
const TYPES=['Expense','Income','Transfer','Refund'];
const DEFAULT_CATS=['Groceries','Restaurants','Gas','Shopping','Pets','Bills','Entertainment','Health','Transportation','Personal Care','Gifts','Other'];
const clone=v=>JSON.parse(JSON.stringify(v));
const el=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((Number(c)||0)/100);
const now=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const thisMonth=()=>now().slice(0,7);
const id=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const monthLabel=m=>new Date(m+'-01T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'});
const shiftMonth=(m,n)=>{let [y,mo]=m.split('-').map(Number),d=new Date(y,mo-1+n,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};
const validDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')&&d<=now()&&!Number.isNaN(Date.parse(d+'T12:00:00'));
const centsInput=s=>money(Number(s||0));
const validAccount=a=>a&&typeof a.id==='string'&&typeof a.name==='string'&&GROUPS.includes(a.group)&&Number.isSafeInteger(a.opening);
const validTx=t=>t&&typeof t.id==='string'&&typeof t.account==='string'&&TYPES.includes(t.type)&&Number.isSafeInteger(t.cents)&&t.cents>0&&typeof t.description==='string'&&validDate(t.date);
function normalize(raw){if(!raw||!Array.isArray(raw.accounts)||!Array.isArray(raw.transactions)||!raw.accounts.every(validAccount)||!raw.transactions.every(validTx))return null;let x=clone(raw);x.transactions.forEach((t,i)=>{if(!Number.isSafeInteger(t.entryOrder))t.entryOrder=i+1});x.categories=Array.isArray(x.categories)?x.categories:DEFAULT_CATS.map((name,i)=>({id:'cat'+i,name,icon:'◇',color:'#AD8051'}));return x}
let data;try{data=normalize(JSON.parse(localStorage.getItem(DATA_KEY)))}catch{};
if(!data)data={accounts:[],transactions:[],categories:DEFAULT_CATS.map((name,i)=>({id:'cat'+i,name,icon:'◇',color:'#AD8051'}))};
let prefs;try{prefs=JSON.parse(localStorage.getItem(UI_KEY))||{}}catch{prefs={}};
prefs.openGroups??=prefs.expanded||[];prefs.summaryOpen??=false;prefs.hide??=false;prefs.defaultAccount??='';prefs.onboarded??=data.accounts.length>0;
delete prefs.theme;
try{localStorage.setItem(UI_KEY,JSON.stringify(prefs))}catch{}
let page='wallet',currentAccount=null,currentMonth=thisMonth(),expanded=null,searchExpanded=null,origin='wallet',editId=null,formDrafts={},draftType='Expense',batch=[],searchQuery='',searchFilters=false,searchFilter={account:'',type:'',category:'',from:'',to:''},searchSort='new',stickySearch=null,categoryId=null,settingsReturn='settings',accountEditId=null,accountMenuOpen=false,toastTimer,undoAction=null,restoreFile=null;
const persist=()=>{try{localStorage.setItem(DATA_KEY,JSON.stringify(data));localStorage.setItem(UI_KEY,JSON.stringify(prefs));return true}catch(e){alert('Could not save to this browser. Check available storage and export a backup.');return false}};
const persistPrefs=()=>{try{localStorage.setItem(UI_KEY,JSON.stringify(prefs))}catch{}};
const nextEntryOrder=()=>data.transactions.reduce((n,t)=>Math.max(n,t.entryOrder||0),0)+1;
const newestEntryFirst=(a,b)=>(b.entryOrder||0)-(a.entryOrder||0);
const account=id=>data.accounts.find(a=>a.id===id);
const active=()=>data.accounts.filter(a=>!a.archived);
const category=id=>data.categories.find(c=>c.id===id)?.name||'Uncategorized';
const accountName=id=>account(id)?.name||'Account';
const sign=(t,a)=>{if(t.account!==a.id)return 0;let debt=a.group==='Debts';if(t.type==='Transfer')return t.direction==='out'?(debt?t.cents:-t.cents):(debt?-t.cents:t.cents);return t.type==='Expense'?(debt?t.cents:-t.cents):(debt?-t.cents:t.cents)};
const balance=a=>a.opening+data.transactions.reduce((v,t)=>v+sign(t,a),0);
const groupTotal=g=>active().filter(a=>a.group===g).reduce((v,a)=>v+balance(a),0);
const visibleMoney=c=>prefs.hide?'••••••':money(c);
const field=(name,title,html)=>`<label class="field" for="${name}"><span>${title}</span>${html}</label>`;
const textInput=(name,value='',extra='')=>`<input id="${name}" name="${name}" value="${esc(value)}" ${extra}>`;
const opts=(arr,selected)=>arr.map(([val,label])=>`<option value="${esc(val)}" ${val===selected?'selected':''}>${esc(label)}</option>`).join('');
const accountsOptions=(selected,includeEmpty=false)=>`${includeEmpty?'<option value="">All accounts</option>':''}${GROUPS.map(g=>`<optgroup label="${g}">${active().filter(a=>a.group===g).map(a=>`<option value="${esc(a.id)}" ${selected===a.id?'selected':''}>${esc(a.name)} · ${visibleMoney(balance(a))}</option>`).join('')}</optgroup>`).join('')}`;
const catsOptions=(selected,all=false)=>`<option value="">${all?'All categories':'Uncategorized'}</option>${opts(data.categories.map(c=>[c.id,`${c.icon||'◇'} ${c.name}`]),selected)}`;
// Illustrated, reusable account motifs — consistent with the Mi Carterita palette.
const illustratedIcon=(kind)=>{
 const shape={
 wallet:`<path d="M8 13V9.5Q8 7 11 7H29Q32 7 32 10V14" fill="#F5A7BA"/><rect x="7" y="13" width="28" height="22" rx="5" fill="#B84469"/><path d="M11 16h22v15H11z" fill="#F7B8C6"/><path d="M26 21h11v9H26a4.5 4.5 0 0 1 0-9" fill="#8D284B"/><circle cx="30" cy="25.5" r="1.5" fill="#F9D27A"/><path d="M12 10h16" stroke="#FFF3E9"/>`,
 pig:`<path d="M10 21q-3-3-1-8l6 2q9-7 19 0l5-2 1 8q4 7-3 13l-1 5h-6l-1-3H19l-1 3h-6l-1-6q-5-4-1-12" fill="#FFB6C6"/><ellipse cx="25" cy="24" rx="6" ry="4" fill="#F18DA6"/><circle cx="23" cy="24" r="1" fill="#923655"/><circle cx="27" cy="24" r="1" fill="#923655"/><circle cx="16" cy="20" r="1.6" fill="#7E2945"/><circle cx="34" cy="20" r="1.6" fill="#7E2945"/><circle cx="17" cy="24" r="3" fill="#F58EA5" opacity=".7"/><circle cx="34" cy="24" r="3" fill="#F58EA5" opacity=".7"/><circle cx="23" cy="10" r="7" fill="#FFD36D" stroke="#A76B27" stroke-width="2"/><path d="M23 6v8m3-6h-5q-2 2 2 2t0 3h-4" fill="none" stroke="#9A5A20" stroke-width="1.4"/>`,
 sprout:`<path d="M24 38V19" fill="none" stroke="#668456" stroke-width="3"/><path d="M24 27Q9 26 10 13q13-1 14 14" fill="#A7C48C"/><path d="M24 23q1-14 15-13 0 14-15 13" fill="#87AF78"/><path d="M17 38h15" stroke="#8C4B45" stroke-width="3"/><path d="M20 33h9l-2 8h-5z" fill="#EFA0A7"/>`,
 card:`<rect x="6" y="12" width="36" height="25" rx="5" fill="#F5A8B9"/><path d="M7 20h34" stroke="#852D48" stroke-width="4"/><path d="M12 31h10" stroke="#FFF7F4" stroke-width="3"/>`,
 bank:`<path d="M5 17 24 7l19 10v4H5z" fill="#F2A7B9"/><path d="M9 23v13m10-13v13m10-13v13m10-13v13" stroke="#852D48" stroke-width="4"/><path d="M5 39h38M8 22h32" stroke="#852D48" stroke-width="3"/>`,
 cash:`<rect x="5" y="14" width="36" height="23" rx="3" transform="rotate(-8 23 25)" fill="#F3B0C1"/><rect x="8" y="17" width="31" height="18" rx="2" transform="rotate(-8 23 25)" fill="#FCE2E1"/><circle cx="24" cy="26" r="7" fill="#F8C76C"/><path d="M24 21v10m4-8q-8-4-8 1t8 4q1 4-8 2" fill="none" stroke="#8E4A31" stroke-width="1.7"/>`
 }[kind]||'';
 return `<svg class="illustrated-icon" viewBox="0 0 48 48" role="img" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><g stroke="#852D48" stroke-width="1.7" stroke-linejoin="round" stroke-linecap="round">${shape}</g></svg>`;
};
const groupIcon=g=>illustratedIcon(({'Everyday Money':'wallet','Savings':'pig','Retirement':'sprout','Debts':'card'})[g]);
const accountIcon=a=>{if(a.icon&&!['▣','▤','♧','✧'].includes(a.icon))return esc(a.icon);const n=a.name.toLowerCase();if(/cash|efectivo/.test(n))return illustratedIcon('cash');if(/checking|bank|debit|cuenta/.test(n))return illustratedIcon('bank');return groupIcon(a.group)};
const accountSubtitle=a=>a.group==='Everyday Money'?(/cash|efectivo/i.test(a.name)?'Physical cash':'Available balance'):a.group==='Debts'?'Outstanding balance':a.group==='Retirement'?'Retirement funds':'Saved funds';
const nav=()=>`<nav class="bottom" aria-label="Main navigation"><button data-nav="wallet" class="${(page==='wallet'||page==='ledger')?'active':''}"><span class="navicon"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="6" width="18" height="15" rx="2"/><path d="M3 10h18M7 6V4h11"/><circle cx="16.5" cy="15.5" r="1"/></svg></span>Mi Carterita</button><button data-nav="settings" class="${page==='settings'?'active':''}"><span class="navicon"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 2.5 14 4l2.4-.4.9 2.4 2.3 1 .1 2.5 1.8 1.7-1 2.3 1 2.3-1.8 1.7-.1 2.5-2.3 1-.9 2.4L14 22l-2 1.5L10 22l-2.4.4-.9-2.4-2.3-1-.1-2.5L2.5 15l1-2.3-1-2.3 1.8-1.7.1-2.5 2.3-1 .9-2.4L10 4z" transform="translate(0 -1) scale(1 .95)"/><circle cx="12" cy="12" r="3"/></svg></span>Settings</button></nav>`;
const header=(title,back=false)=>back?`<header class="backhead"><button class="iconbtn" data-action="back" aria-label="Go back">‹</button><div><div class="eyebrow">PESITO A PESITO <span class="eyebrow-flower" aria-hidden="true">✿</span></div><h1>${esc(title)}</h1></div></header>`:`<header class="top"><div><div class="eyebrow">PESITO A PESITO <span class="eyebrow-flower" aria-hidden="true">✿</span></div><h1>${esc(title)}</h1>${title==='Mi Cartera'?'<div class="subtitle">Every little peso counts.</div>':''}</div><div class="topright"><button class="iconbtn" data-action="hide" aria-label="Toggle balance privacy">${prefs.hide?'◉':'◎'}</button><img class="mini-pig" src="icon-192.png" alt="Pesito a Pesito piggy"></div></header>`;
function welcome(){return `<div class="welcome card"><img src="icon-192.png" alt="Pesito a Pesito piggy"><div class="eyebrow">WELCOME TO YOUR CAR​TERA</div><h2>Every little peso counts.</h2><p>Make this little space yours. Your records stay in this browser, not on GitHub.</p><button data-action="start-empty">Start with my own accounts</button><small>Start with no accounts or balances. Add your own information whenever you are ready.</small></div>`}
function walletMonthTotals(month=thisMonth()){
 let income=0,spending=0;
 const debtDestinations=new Set(data.transactions.filter(t=>t.type==='Transfer'&&t.direction==='in'&&t.link&&account(t.account)?.group==='Debts').map(t=>t.link));
 for(const t of data.transactions){
  const a=account(t.account);
  if(!a||t.date.slice(0,7)!==month)continue;
  if(t.type==='Income'&&a.group!=='Debts')income+=t.cents;
  if(a.group!=='Everyday Money')continue;
  if(t.type==='Expense')spending+=t.cents;
  if(t.type==='Refund')spending-=t.cents;
  if(t.type==='Transfer'&&t.direction==='out'&&t.link&&debtDestinations.has(t.link))spending+=t.cents;
 }
 return {income,spending}
}
function walletSnapshot(netWorth){const totals=walletMonthTotals();return `<section class="illustrated-snapshot" aria-label="Financial snapshot for ${esc(monthLabel(thisMonth()))}"><img src="file_00000000b49482128971c9575298a97e.png" alt=""><strong class="snapshot-live snapshot-net" aria-label="Net Worth ${visibleMoney(netWorth)}">${visibleMoney(netWorth)}</strong><strong class="snapshot-live snapshot-income" aria-label="Monthly Income ${visibleMoney(totals.income)}" title="Income recorded this calendar month; transfers and debt payments excluded">${visibleMoney(totals.income)}</strong><strong class="snapshot-live snapshot-spent" aria-label="Monthly Spending ${visibleMoney(totals.spending)}" title="Everyday Money expenses minus refunds, plus Everyday-to-Debt payments this calendar month; other transfers and credit purchases excluded">${visibleMoney(totals.spending)}</strong></section>`}
function wallet(){let available=groupTotal('Everyday Money'),savings=groupTotal('Savings')+groupTotal('Retirement'),debt=groupTotal('Debts');return `<div class="wallet-banner rectangular-banner"><img src="file_000000003e908212848393b545d8854c.png" alt="Mi Carterita — waving piggy, pastel wallet, books and gold coins"><button class="banner-privacy" data-action="hide" aria-label="${prefs.hide?'Show financial amounts':'Hide financial amounts'}" aria-pressed="${prefs.hide}" title="${prefs.hide?'Show balances':'Hide balances'}">${prefs.hide?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18M10.6 5.1A10.8 10.8 0 0 1 12 5c5.2 0 9 5 9 7a11 11 0 0 1-3.1 3.7M6.3 6.3C4.1 7.7 3 10.2 3 12c0 2 3.8 7 9 7 1.7 0 3.3-.5 4.6-1.3M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.7-7 10-7 10 7 10 7-3.7 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>'}</button></div>${!prefs.onboarded?welcome():`<section class="overview"><div class="botanical-summary"><img class="botanical-summary-image" src="file_00000000344481f7bdae9d7c40984d3e.png" alt=""><span class="botanical-balance botanical-available" aria-label="Total Available Money ${visibleMoney(available)}">${visibleMoney(available)}</span><span class="botanical-balance botanical-debt" aria-label="Total Debt ${visibleMoney(debt)}">${visibleMoney(debt)}</span><span class="botanical-balance botanical-savings" aria-label="Savings and Retirement ${visibleMoney(savings)}">${visibleMoney(savings)}</span></div><section class="snapshot-disclosure ${prefs.snapshotOpen===true?'is-open':''}" id="financial-snapshot"><button class="snapshot-toggle" data-action="toggle-snapshot" aria-expanded="${prefs.snapshotOpen===true}" aria-controls="snapshot-reveal"><span>Financial Snapshot</span><svg class="snapshot-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><div class="snapshot-reveal" id="snapshot-reveal" aria-hidden="${prefs.snapshotOpen!==true}" ${prefs.snapshotOpen===true?'':'inert'}><div class="snapshot-reveal-inner">${walletSnapshot(available+savings-debt)}</div></div></section></section><div class="quick"><button class="soft" data-action="new-account">＋ Account</button><button data-action="new-expense">＋ Transaction</button></div><div class="sectiontitle floral-heading"><h2 class="accounts-art-title"><svg class="accounts-heading-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1847 309" role="img" aria-label="Your Accounts"><path fill="#fad6e6" d="M 136 125 C 102 87 66 82 43 101 C 20 123 35 153 62 178 C 96 211 136 237 177 261 C 191 222 214 163 226 110 C 239 56 220 28 197 30 C 163 33 145 75 136 125 Z"/><image href="./your-accounts-art.png" x="0" y="0" width="1847" height="309"/></svg></h2><button class="ghost tiny" data-nav="settings">Manage ›</button></div>${GROUPS.map(g=>`<details class="group" data-group="${g}" ${prefs.openGroups.includes(g)?'open':''}><summary><span class="group-label"><span class="group-symbol">${groupIcon(g)}</span><span class="group-copy"><b>${g}</b><small>${active().filter(a=>a.group===g).length} ${active().filter(a=>a.group===g).length===1?"account":"accounts"}</small></span></span><span class="group-end"><b>${visibleMoney(groupTotal(g))}</b><span class="group-arrow" aria-hidden="true"><svg viewBox="0 0 20 20"><path d="m4 7 6 6 6-6"/></svg></span></span></summary>${active().filter(a=>a.group===g).sort((a,b)=>balance(b)-balance(a)||a.name.localeCompare(b.name)).map(a=>`<button class="account" data-account="${esc(a.id)}"><span class="accountname"><span class="tile">${accountIcon(a)}</span><span class="account-copy"><b>${esc(a.name)}</b><small>${accountSubtitle(a)}</small></span></span><strong>${visibleMoney(balance(a))} <span class="chev">›</span></strong></button>`).join('')||'<div class="emptyline">No accounts yet</div>'}</details>`).join('')}`}`}
function signedAmount(t){let a=account(t.account);if(!a)return visibleMoney(t.cents);let positive=sign(t,a)>0;return `<strong class="${positive?'positive':'negative'}">${prefs.hide?'':positive?'+':'−'}${visibleMoney(t.cents)}</strong>`}
function details(t,context){return `<div class="entrydetail"><p><b>Type</b> ${esc(t.type)}${t.type==='Transfer'?' · '+esc(t.direction):''}</p><p><b>Account</b> ${esc(accountName(t.account))}</p><p><b>Category</b> ${esc(category(t.category))}</p>${t.notes?`<p><b>Notes</b> ${esc(t.notes)}</p>`:''}<div class="actions"><button class="soft" data-edit="${esc(t.id)}" data-context="${context}">Edit</button><button class="line" data-delete="${esc(t.id)}">Delete</button></div></div>`}
function transactionRow(t,context){let dt=new Date(t.date+'T12:00:00'),open=(context==='ledger'?expanded:searchExpanded)===t.id;return `<div class="entry"><button class="entryrow" data-expand="${esc(t.id)}" data-context="${context}"><span class="date">${dt.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}<small>${dt.toLocaleDateString('en-US',{weekday:'short'})}</small></span><span class="desc">${esc(t.description)}</span>${signedAmount(t)}</button>${open?details(t,context):''}</div>`}
function ledger(){let a=account(currentAccount);if(!a){page='wallet';return wallet()}let items=data.transactions.filter(t=>t.account===a.id&&t.date.slice(0,7)===currentMonth).sort(newestEntryFirst);let incoming=0,outgoing=0;items.forEach(t=>{let v=sign(t,a);if(v>0)incoming+=v;else outgoing-=v});let net=incoming-outgoing;return `${header(a.name,true)}<div class="account-toolbar"><span class="account-type">${esc(a.group)} account</span><button class="account-options-button" data-action="toggle-account-options" aria-label="Account options" aria-expanded="${accountMenuOpen}">⋯</button></div>${accountMenuOpen?`<div class="account-options"><button data-action="edit-current-account">✎ &nbsp; Edit account</button><button data-action="adjust-current-account">⚖ &nbsp; Adjust balance</button><button class="danger" data-action="delete-current-account">♲ &nbsp; Delete account</button></div>`:''}<div class="card balancecard"><small>Current balance</small><div class="big">${visibleMoney(balance(a))}</div></div>${installmentOverview(a)}<div class="ledgerquick"><button class="soft" data-action="ledger-expense">− Expense</button><button class="soft" data-action="ledger-income">＋ Income</button><button class="soft" data-action="ledger-transfer">⇄ Transfer</button></div><div class="monthnav"><button data-action="prev-month" aria-label="Previous month">‹</button><strong>${monthLabel(currentMonth)}</strong><button data-action="next-month" aria-label="Next month" ${currentMonth>=thisMonth()?'disabled':''}>›</button></div><details class="summary" id="monthly" ${prefs.summaryOpen?'open':''}><summary>Monthly summary</summary><div class="summarygrid"><div><small>Money In</small><strong class="positive">${visibleMoney(incoming)}</strong></div><div><small>Money Out</small><strong>${visibleMoney(outgoing)}</strong></div><div><small>Net Change</small><strong class="${net>0?'positive':net<0?'negative':''}">${prefs.hide?'':net<0?'−':''}${visibleMoney(Math.abs(net))}</strong></div></div></details>${items.length?`<div class="tablehead"><span>Date</span><span>Description</span><span>Amount</span></div>${items.map(t=>transactionRow(t,'ledger')).join('')}`:`<section class="detective"><button class="detective-action" data-action="ledger-expense" aria-label="Add transaction for this month"><img src="detective-art.png" alt="No transactions this month. Add Transaction."></button></section>`}`}
function freshDraft(type){let def=(page==='ledger'?currentAccount:null)||prefs.defaultAccount||active()[0]?.id||'';return {type,description:'',digits:'',account:def,date:page==='ledger'&&currentMonth!==thisMonth()?currentMonth+'-01':now(),category:'',notes:'',from:def,to:active().find(a=>a.id!==def)?.id||''}}
function begin(type='Expense',t=null,from=null){origin=from||((page==='ledger'||page==='search')?page:'wallet');editId=t?.id||null;draftType=type;formDrafts={};if(t){let out=t.type==='Transfer'?data.transactions.find(x=>x.link===t.link&&x.direction==='out'):null;let inc=t.type==='Transfer'?data.transactions.find(x=>x.link===t.link&&x.direction==='in'):null;formDrafts[type]={...t,digits:String(t.cents),from:out?.account||t.account,to:inc?.account||''}}else formDrafts[type]=freshDraft(type);batch=[];page='editor';render();/* No autofocus: let the user see the full form before the keyboard appears. */}
const draft=()=>formDrafts[draftType]||(formDrafts[draftType]=freshDraft(draftType));
function editor(){let d=draft(),transfer=draftType==='Transfer';if(!active().length)return `${header('Add Transaction',true)}<div class="panel"><p>Add an account before recording transactions.</p><button data-action="new-account">＋ Add account</button></div>`;let originalAccount=origin==='ledger'?currentAccount:prefs.defaultAccount||active()[0]?.id;let mainFields=transfer?`${field('from','From account',`<select id="from" name="from">${accountsOptions(d.from)}</select>`)}<button class="soft tiny" data-action="swap">⇅ Swap accounts</button>${field('to','To account',`<select id="to" name="to">${accountsOptions(d.to)}</select>`)}${d.from===d.to?'<div class="notice">Choose two different accounts.</div>':''}${field('amount','Amount (USD)',textInput('amount',centsInput(d.digits),'inputmode="numeric" autocomplete="off"'))}${field('date','Date',`<input type="date" id="date" name="date" value="${esc(d.date)}" max="${now()}">`)}<details class="more"><summary>More Options</summary>${field('notes','Notes',`<textarea id="notes" name="notes" rows="2" placeholder="Optional notes">${esc(d.notes)}</textarea>`)}</details><p class="helper">Both sides of the transfer stay linked. Transfers are not counted as income or expenses across your whole wallet.</p>`:`${field('description','Description',textInput('description',d.description,'placeholder="What was it for?" maxlength="120" autocomplete="off"'))}<div id="suggestions"></div>${field('amount','Amount (USD)',textInput('amount',centsInput(d.digits),'inputmode="numeric" autocomplete="off"'))}${field('account','Account',`<select id="account" name="account">${accountsOptions(d.account)}</select>`)}${field('date','Date',`<input type="date" id="date" name="date" value="${esc(d.date)}" max="${now()}">`)}<details class="more"><summary>More Options</summary>${field('category','Category',`<select id="category" name="category">${catsOptions(d.category)}</select>`)}<button class="ghost tiny" data-action="new-category">＋ New Category</button>${field('notes','Notes',`<textarea id="notes" name="notes" rows="2" placeholder="Optional notes">${esc(d.notes)}</textarea>`)}</details>`;
return `${header(editId?'Edit Transaction':'Add Transaction',true)}<div class="panel editorpanel">${!editId?`<div class="seg">${TYPES.map(t=>`<button data-type="${t}" class="${draftType===t?'active':''}">${t}</button>`).join('')}</div>`:''}${mainFields}${!editId&&draftType==='Expense'?`<div class="spaced"><button class="ghost" data-action="batch">＋ Add Another</button></div>`:''}${batch.length?`<div class="batchheading"><b>Compra Rápida</b><small>Separate transactions, one save</small></div>${batch.map((r,i)=>`<div class="batchrow"><div class="first"><input data-batch="${i}" data-key="description" aria-label="Purchase description" placeholder="Description" value="${esc(r.description)}"><input data-batch="${i}" data-key="digits" aria-label="Purchase amount" inputmode="numeric" value="${centsInput(r.digits)}"><button data-remove="${i}" aria-label="Remove purchase">×</button></div><div class="second"><select data-batch="${i}" data-key="account" aria-label="Purchase account">${accountsOptions(r.account)}</select><input type="date" data-batch="${i}" data-key="date" max="${now()}" value="${esc(r.date||d.date)}" aria-label="Purchase date"></div></div>`).join('')}`:''}</div><div class="fixedfooter"><button class="line" data-action="cancel-editor">Cancel</button><div class="savewrap">${batch.length?`<small>${batch.length+1} purchases · ${visibleMoney(Number(d.digits||0)+batch.reduce((n,r)=>n+Number(r.digits||0),0))}</small>`:''}<button class="primary" data-action="save-editor" ${!Number(d.digits)||(!transfer&&!d.description?.trim())||(transfer&&(!d.from||!d.to||d.from===d.to))?'disabled':''}>${batch.length?'Save All':'Save'}</button></div></div>`}
function search(){let list=data.transactions.slice(),q=searchQuery.trim().toLowerCase();if(q)list=list.filter(t=>[t.description,t.notes,category(t.category),String(t.cents/100),money(t.cents)].some(v=>String(v||'').toLowerCase().includes(q)));if(searchFilter.account)list=list.filter(t=>t.account===searchFilter.account);if(searchFilter.type)list=list.filter(t=>t.type===searchFilter.type);if(searchFilter.category)list=list.filter(t=>t.category===searchFilter.category);if(searchFilter.from)list=list.filter(t=>t.date>=searchFilter.from);if(searchFilter.to)list=list.filter(t=>t.date<=searchFilter.to);if(stickySearch&&!list.some(t=>t.id===stickySearch)){let t=data.transactions.find(t=>t.id===stickySearch);if(t)list.unshift(t)}list.sort((a,b)=>searchSort==='old'?-newestEntryFirst(a,b):searchSort==='high'?b.cents-a.cents:searchSort==='low'?a.cents-b.cents:newestEntryFirst(a,b));return `${header('Smart Search')}<div class="searchbar"><span>⌕</span><input id="search-input" placeholder="Search all transactions" value="${esc(searchQuery)}"><button class="ghost tiny" data-action="filters">☷</button></div>${searchFilters?`<div class="panel filters">${field('filter-account','Account',`<select id="filter-account"><option value="">All accounts</option>${accountsOptions(searchFilter.account)}</select>`)}${field('filter-type','Type',`<select id="filter-type"><option value="">All types</option>${opts(TYPES.map(t=>[t,t]),searchFilter.type)}</select>`)}${field('filter-category','Category',`<select id="filter-category">${catsOptions(searchFilter.category,true)}</select>`)}<div class="twocol">${field('filter-from','From',`<input type="date" id="filter-from" value="${esc(searchFilter.from)}">`)}${field('filter-to','To',`<input type="date" id="filter-to" value="${esc(searchFilter.to)}">`)}</div><button class="soft tiny" data-action="clear-filters">Clear filters</button></div>`:''}<div class="sectiontitle spaced"><h2>${q?'Results':'Recent activity'}</h2><select id="search-sort" aria-label="Sort results">${opts([['new','Newest'],['old','Oldest'],['high','Highest Amount'],['low','Lowest Amount']],searchSort)}</select></div>${list.length?list.map(t=>`<div class="searchitem"><button data-expand="${esc(t.id)}" data-context="search"><span><b>${esc(t.description)}</b><small>${esc(accountName(t.account))} · ${esc(t.date)}</small></span>${signedAmount(t)}</button>${searchExpanded===t.id?details(t,'search'):''}</div>`).join(''):'<div class="panel muted">No transactions found yet.</div>'}`}
function settings(){return `${header('Settings')}<div class="panel settings-search"><div class="settingsrow"><span><span class="floral-small">✿</span> Find a transaction<small>Search all accounts and past activity</small></span><button class="soft tiny" data-action="open-search">Search ›</button></div></div><div class="panel"><h2>Preferences</h2><div class="settingsrow"><span>Hide balances</span><button class="soft tiny" data-action="hide">${prefs.hide?'Show':'Hide'}</button></div>${active().length?field('default-account','Default spending account',`<select id="default-account">${accountsOptions(prefs.defaultAccount)}</select>`):''}</div><div class="panel"><h2>Accounts</h2>${data.accounts.map(a=>`<div class="settingsrow"><span>${esc(a.name)} <small>· ${esc(a.group)}</small></span><button class="soft tiny" data-manage-account="${esc(a.id)}">Edit</button></div>`).join('')}<button class="soft spaced" data-action="new-account">＋ Add account</button></div><div class="panel"><h2>Categories</h2>${data.categories.map(c=>`<div class="categoryrow"><span><span style="color:${/^#[0-9a-fA-F]{6}$/.test(c.color||'')?c.color:'#AD8051'}">${esc(c.icon||'◇')}</span> ${esc(c.name)}</span><button class="soft tiny" data-category="${esc(c.id)}">Edit</button></div>`).join('')}<button class="soft spaced" data-action="new-category">＋ New category</button></div><div class="panel"><h2>Backup & restore</h2><p class="privacy">Your data is stored locally in this browser, not on GitHub. It is not encrypted. Keep exported files private; uninstalling or clearing site data may erase records.</p><button data-action="export">↓ Export backup</button>${field('restore','Restore backup',`<input id="restore" type="file" accept=".json,application/json">`)}</div><div class="panel"><h2>Testing & sample data</h2><p class="privacy">Only use this to clear sample data or start fresh. This cannot be undone without a backup.</p><button class="line" data-action="reset">Start fresh / clear records</button></div><p class="privacy">Pesito a Pesito · v1.8 · Offline-ready · No bank connections</p>`}
function accountForm(){let a=account(accountEditId);return `${header(a?'Edit Account':'Add Account',true)}<div class="panel">${field('account-name','Account name',textInput('account-name',a?.name||'','maxlength="60" placeholder="e.g. Checking"'))}${field('account-group','Account group',`<select id="account-group">${opts(GROUPS.map(g=>[g,g]),a?.group||GROUPS[0])}</select>`)}${a?'<p class="helper">To correct a balance, use Adjust Balance from the account menu.</p>':field('opening','Opening balance (USD)',textInput('opening',money(0),'inputmode="numeric" autocomplete="off"'))}${field('debt-kind','Debt account type',`<select id="debt-kind">${opts([['standard','Standard debt / credit card'],['installment','Installment / Buy Now, Pay Later']],a?.debtKind||'standard')}</select>`)}${field('account-icon','Icon (optional)',textInput('account-icon',a?.icon||'','maxlength="3" placeholder="♡"'))}<p class="helper">Opening balance is the amount already in the account when you start tracking. For debts, enter what you owe.</p></div>${a?`<div class="panel"><button class="danger" data-action="delete-edited-account">Delete account</button><p class="helper">Deleting also removes this account’s transactions. This cannot be undone without a backup.</p></div>`:''}<div class="fixedfooter"><button class="line" data-action="back">Cancel</button><button data-action="save-account">Save account</button></div>`}
function categoryForm(){let c=data.categories.find(x=>x.id===categoryId);return `${header(c?'Edit Category':'New Category',true)}<div class="panel">${field('category-name','Name',textInput('category-name',c?.name||'','maxlength="50"'))}<div class="twocol">${field('category-icon','Icon',textInput('category-icon',c?.icon||'◇','maxlength="3"'))}${field('category-color','Color',`<input type="color" id="category-color" value="${esc(c?.color||'#AD8051')}">`)}</div>${c?'<button class="danger tiny" data-action="delete-category">Delete category</button>':''}</div><div class="fixedfooter"><button class="line" data-action="back">Cancel</button><button data-action="save-category">Save category</button></div>`}
function adjustAccountPage(){let a=account(currentAccount);if(!a)return wallet();return `${header('Adjust Balance',true)}<div class="panel"><h2>${esc(a.name)}</h2><p class="helper">Current balance: <b>${visibleMoney(balance(a))}</b></p>${field('target-balance','Correct balance (USD)',textInput('target-balance',(balance(a)/100).toFixed(2),'inputmode="decimal"'))}<p class="helper">This records a balance correction in the account’s opening balance. Existing transactions stay unchanged.</p><button class="primary" data-action="save-adjustment">Save balance correction</button></div>`}
function deleteCurrentAccount(accountId=currentAccount){let a=account(accountId);if(!a)return;let linked=data.transactions.filter(t=>t.account===a.id&&t.link),count=data.transactions.filter(t=>t.account===a.id).length;if(linked.length){alert('This account has linked transfers. To protect other account balances, delete or move those transfers first.');return}if(!confirm(`Delete ${a.name} and its ${count} transaction${count===1?'':'s'} permanently? This cannot be undone. Export a backup first if you want to preserve them.`))return;data.transactions=data.transactions.filter(t=>t.account!==a.id);data.accounts=data.accounts.filter(x=>x.id!==a.id);if(prefs.defaultAccount===a.id)prefs.defaultAccount=active()[0]?.id||'';currentAccount=null;accountMenuOpen=false;page='wallet';persist();render();toast('Account deleted')}
let exitBackDeadline=0,allowHistoryExit=false,restoreExitGuard=()=>{};
function render(keep=false){if(exitBackDeadline)restoreExitGuard();exitBackDeadline=0;let scroll=window.scrollY;el('#app').innerHTML=`<main class="shell">${page==='wallet'?wallet():page==='ledger'?ledger():page==='editor'?editor():page==='search'?search():page==='settings'?settings():page==='account-form'?accountForm():page==='adjust-account'?adjustAccountPage():page==='category-form'?categoryForm():wallet()}</main>${nav()}`;syncDebtKindField();if(keep)window.scrollTo(0,scroll);else window.scrollTo(0,0)}
function toast(message,callback){clearTimeout(toastTimer);undoAction=callback||null;let box=el('#toast');box.innerHTML=`${esc(message)}${callback?'<button id="undo">Undo</button>':''}`;box.style.display='block';if(callback)el('#undo').onclick=()=>{callback();box.style.display='none';undoAction=null};toastTimer=setTimeout(()=>{box.style.display='none';undoAction=null},10000)}
function back(){if(closePlanDialog())return;if(page==='editor'){let d=draft();let dirty=editId||d.description||Number(d.digits)||batch.some(r=>r.description||Number(r.digits))||d.notes;if(dirty&&!confirm('Discard unsaved changes?'))return;page=origin;editId=null}else if(page==='ledger'){page='wallet';currentAccount=null}else if(page==='category-form'){page=settingsReturn==='editor'?'editor':'settings'}else if(page==='account-form'){page='settings';accountEditId=null}else page='wallet';render()}
function syncEditor(){if(page!=='editor')return;let d=draft();for(let name of ['description','account','date','category','notes','from','to']){let input=el(`[name="${name}"]`);if(input)d[name]=input.value}}
function commitEditor(){syncEditor();let d=draft(),cents=Number(d.digits||0);if(!Number.isSafeInteger(cents)||cents<=0)return toast('Enter an amount greater than $0.00');if(!validDate(d.date))return toast('Choose today or an earlier date');if(draftType==='Transfer'){if(!account(d.from)||!account(d.to)||d.from===d.to)return toast('Choose two different accounts');let prior=editId?data.transactions.find(t=>t.id===editId):null,entryOrder=prior?.entryOrder??nextEntryOrder(),created=prior?.created||new Date().toISOString();let link=prior?.link||id();if(editId)data.transactions=data.transactions.filter(t=>t.link!==link);let outId=id(),inId=id();data.transactions.push({id:outId,link,entryOrder,created,type:'Transfer',direction:'out',account:d.from,description:'Transfer to '+accountName(d.to),cents,date:d.date,notes:d.notes||'',category:''},{id:inId,link,entryOrder,created,type:'Transfer',direction:'in',account:d.to,description:'Transfer from '+accountName(d.from),cents,date:d.date,notes:d.notes||'',category:''});expanded=outId;searchExpanded=outId;stickySearch=outId}else{if(!d.description?.trim()||!account(d.account))return toast('Enter description and account');let rows=[{description:d.description.trim(),account:d.account,cents,date:d.date,category:d.category||'',notes:d.notes||''}];if(batch.length){for(let r of batch){if(!r.description?.trim()&&!Number(r.digits||0))continue;if(!r.description?.trim()||!Number(r.digits)||!account(r.account)||!validDate(r.date||d.date))return toast('Complete every started purchase before saving');rows.push({description:r.description.trim(),account:r.account,cents:Number(r.digits),date:r.date||d.date,category:'',notes:''})}}if(editId){let t=data.transactions.find(t=>t.id===editId);if(!t)return toast('Transaction not found');Object.assign(t,rows[0],{type:draftType});expanded=t.id;searchExpanded=t.id;stickySearch=t.id}else{rows.forEach((r,i)=>{let tx={id:id(),type:draftType,...r,created:new Date().toISOString(),entryOrder:nextEntryOrder()};data.transactions.push(tx);if(i===0){expanded=tx.id;searchExpanded=tx.id;stickySearch=tx.id}})}}let dest=draftType==='Transfer'?d.from:d.account;page=origin==='search'?'search':'ledger';if(page==='ledger'){currentAccount=dest;currentMonth=d.date.slice(0,7)}editId=null;if(persist()){render();toast('Saved') }}
function resetSearch(){searchQuery='';searchFilter={account:'',type:'',category:'',from:'',to:''};searchSort='new';searchExpanded=null;stickySearch=null;searchFilters=false;page='search';render()}
function exportBackup(){let b=new Blob([JSON.stringify({format:'pesito-a-pesito-backup-v1',exported:new Date().toISOString(),...data},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`pesito-backup-${now()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function saveAccount(){let name=el('#account-name')?.value.trim(),group=el('#account-group')?.value,raw=el('#opening')?.value.trim().replace(/[$,\s]/g,'');if(!name)return toast('Enter an account name');if(!GROUPS.includes(group)||(!account(accountEditId)&&!/^\d+(\.\d{0,2})?$/.test(raw)))return toast('Enter a valid nonnegative balance');let cents=account(accountEditId)?.opening??Math.round(Number(raw)*100);if(!Number.isSafeInteger(cents))return toast('Balance is too large');let a=account(accountEditId),props={name,group,opening:cents,icon:el('#account-icon')?.value||'',debtKind:group==='Debts'?el('#debt-kind').value:'standard'};if(a?.plans?.length&&props.debtKind!=='installment')return toast('Keep Installment selected while purchase plans exist');if(a)Object.assign(a,props);else{a={id:id(),...props};data.accounts.push(a);if(!prefs.defaultAccount)prefs.defaultAccount=a.id}prefs.onboarded=true;persist();page='wallet';currentAccount=null;accountEditId=null;accountMenuOpen=false;render();toast('Account saved')}
function saveCategory(){let name=el('#category-name')?.value.trim();if(!name)return toast('Enter category name');let c=data.categories.find(x=>x.id===categoryId),props={name,icon:el('#category-icon')?.value||'◇',color:el('#category-color')?.value||'#AD8051'};if(c)Object.assign(c,props);else{c={id:id(),...props};data.categories.push(c);if(settingsReturn==='editor')draft().category=c.id}persist();page=settingsReturn==='editor'?'editor':'settings';render();toast('Category saved')}
// Event delegation keeps event handlers stable after each render.
document.addEventListener('toggle',e=>{if(e.target.matches('.group')){let g=e.target.dataset.group;prefs.openGroups=prefs.openGroups.filter(x=>x!==g);if(e.target.open)prefs.openGroups.push(g);persistPrefs()}if(e.target.id==='financial-snapshot'){prefs.snapshotOpen=e.target.open;persistPrefs()}if(e.target.id==='monthly'){prefs.summaryOpen=e.target.open;persistPrefs()}},true);
// Native numeric keypad behavior: each typed digit shifts cents, and backspace removes one digit.
document.addEventListener('beforeinput',e=>{let x=e.target;if(page==='account-form'&&x.id==='opening'){let digits=x.value.replace(/\D/g,'').replace(/^0+/,'');if(e.inputType==='insertText'&&/^\d+$/.test(e.data||'')||e.inputType==='deleteContentBackward'||e.inputType==='deleteContentForward'){e.preventDefault();let selected=x.selectionStart!==x.selectionEnd;if(selected){let start=x.value.slice(0,x.selectionStart).replace(/\D/g,'').length,end=x.value.slice(0,x.selectionEnd).replace(/\D/g,'').length;let raw=x.value.replace(/\D/g,'');digits=(raw.slice(0,start)+(e.inputType==='insertText'?e.data:'')+raw.slice(end)).replace(/^0+/,'')}else digits=e.inputType==='insertText'?(digits+e.data).replace(/^0+/,''):digits.slice(0,-1);digits=digits.slice(0,12);x.value=centsInput(digits);x.setSelectionRange(x.value.length,x.value.length)}return}if(page!=='editor'||!x.matches('#amount,[data-key="digits"]'))return;if(e.inputType==='insertText'&&/^\d$/.test(e.data||'')||e.inputType==='deleteContentBackward'){let target=x.id==='amount'?draft():batch[Number(x.dataset.batch)];if(!target)return;e.preventDefault();let old=String(target.digits||'');target.digits=e.inputType==='deleteContentBackward'?old.slice(0,-1):(old+(e.data||'')).replace(/^0+/,'').slice(0,12);x.value=centsInput(target.digits);if(x.id==='amount'){let d=draft(),save=el('[data-action="save-editor"]');if(save)save.disabled=!Number(d.digits)||(!d.description?.trim()&&draftType!=='Transfer')||(draftType==='Transfer'&&d.from===d.to)}x.setSelectionRange(x.value.length,x.value.length)}});
document.addEventListener('input',e=>{let x=e.target;if(page==='account-form'&&x.id==='opening'){let digits=x.value.replace(/\D/g,'').replace(/^0+/,'').slice(0,12);x.value=centsInput(digits);x.setSelectionRange(x.value.length,x.value.length);return}if(page==='editor'){let d=draft();if(x.name==='amount'){let digits=x.value.replace(/\D/g,'').replace(/^0+/,'').slice(0,12);d.digits=digits;x.value=centsInput(digits);x.setSelectionRange(x.value.length,x.value.length);let save=el('[data-action="save-editor"]');if(save)save.disabled=!Number(digits)||(!d.description?.trim()&&draftType!=='Transfer')||(draftType==='Transfer'&&d.from===d.to);return}if(x.dataset.batch!==undefined){let r=batch[Number(x.dataset.batch)];if(!r)return;if(x.dataset.key==='digits'){r.digits=x.value.replace(/\D/g,'').replace(/^0+/,'').slice(0,12);x.value=centsInput(r.digits);x.setSelectionRange(x.value.length,x.value.length)}else r[x.dataset.key]=x.value;return}if(x.name)d[x.name]=x.value;if(x.name==='description'){let save=el('[data-action="save-editor"]');if(save)save.disabled=!Number(d.digits)||!d.description.trim();let v=x.value.trim().toLowerCase(),found=[...new Set(data.transactions.map(t=>t.description))].filter(s=>v&&s.toLowerCase().includes(v)&&s.toLowerCase()!==v).slice(0,5);let area=el('#suggestions');if(area)area.innerHTML=found.length?`<div class="suggestions">${found.map(s=>`<button data-suggest="${esc(s)}">${esc(s)}</button>`).join('')}</div>`:''}}if(x.id==='search-input'){searchQuery=x.value;let caret=x.selectionStart;render(true);let inp=el('#search-input');inp.focus();inp.setSelectionRange(caret,caret)}});
document.addEventListener('change',async e=>{let x=e.target;if(page==='editor'){if(x.name)draft()[x.name]=x.value;if(x.dataset.batch!==undefined){let r=batch[Number(x.dataset.batch)];if(r&&x.dataset.key!=='digits')r[x.dataset.key]=x.value}}if(x.id==='default-account'){prefs.defaultAccount=x.value;persistPrefs()}if(x.id==='search-sort'){searchSort=x.value;render(true)}for(let k of ['account','type','category','from','to'])if(x.id==='filter-'+k){searchFilter[k]=x.value;render(true)}if(x.id==='restore'&&x.files?.[0]){try{let incoming=normalize(JSON.parse(await x.files[0].text()));if(!incoming)throw Error('Invalid backup');if(confirm('Replace all current records with this backup?')){data=incoming;prefs.onboarded=true;persist();page='wallet';render();toast('Backup restored')}}catch(e){toast('Could not read backup file')}}});
document.addEventListener('click',e=>{let x=e.target.closest('button');if(!x)return;if(x.dataset.nav){let n=x.dataset.nav;if(n==='wallet'){page='wallet';currentAccount=null;render()}else if(n==='search')resetSearch();else if(n==='add')begin();else{page='settings';render()}return}if(x.dataset.account){currentAccount=x.dataset.account;currentMonth=thisMonth();expanded=null;accountMenuOpen=false;page='ledger';render();return}if(x.dataset.expand){if(x.dataset.context==='search')searchExpanded=searchExpanded===x.dataset.expand?null:x.dataset.expand;else expanded=expanded===x.dataset.expand?null:x.dataset.expand;render(true);return}if(x.dataset.edit){let t=data.transactions.find(t=>t.id===x.dataset.edit);if(t){let outgoing=t.type==='Transfer'?data.transactions.find(z=>z.link===t.link&&z.direction==='out'):t;begin(t.type,outgoing||t,x.dataset.context)}return}if(x.dataset.delete){let t=data.transactions.find(t=>t.id===x.dataset.delete);if(!t||!confirm('Delete this transaction?'))return;let removed=data.transactions.filter(z=>z.id===t.id||(t.link&&z.link===t.link));data.transactions=data.transactions.filter(z=>!removed.includes(z));expanded=null;searchExpanded=null;persist();render(true);toast('Transaction deleted',()=>{data.transactions.push(...removed);persist();render(true)});return}if(x.dataset.type){syncEditor();draftType=x.dataset.type;if(!formDrafts[draftType])formDrafts[draftType]=freshDraft(draftType);render();return}if(x.dataset.suggest){draft().description=x.dataset.suggest;render(true);return}if(x.dataset.remove!==undefined){let i=Number(x.dataset.remove),r=batch.splice(i,1)[0];render(true);toast('Purchase removed',()=>{batch.splice(i,0,r);render(true)});return}if(x.dataset.category){categoryId=x.dataset.category;settingsReturn='settings';page='category-form';render();return}if(x.dataset.manageAccount){accountEditId=x.dataset.manageAccount;page='account-form';render();return}
switch(x.dataset.action){case'toggle-snapshot':{prefs.snapshotOpen=!prefs.snapshotOpen;persistPrefs();const box=el('#financial-snapshot'),panel=el('#snapshot-reveal');box.classList.toggle('is-open',prefs.snapshotOpen);x.setAttribute('aria-expanded',String(prefs.snapshotOpen));panel.setAttribute('aria-hidden',String(!prefs.snapshotOpen));panel.inert=!prefs.snapshotOpen;break}case'back':if(page==='adjust-account'){page='ledger';render()}else back();break;case'toggle-account-options':accountMenuOpen=!accountMenuOpen;render(true);break;case'edit-current-account':accountEditId=currentAccount;accountMenuOpen=false;page='account-form';render();break;case'adjust-current-account':accountMenuOpen=false;page='adjust-account';render();break;case'delete-current-account':deleteCurrentAccount();break;case'delete-edited-account':deleteCurrentAccount(accountEditId);break;case'save-adjustment':{let a=account(currentAccount),raw=el('#target-balance')?.value.trim().replace(/[$,\s]/g,'');if(!a||!/^\d+(\.\d{0,2})?$/.test(raw)){toast('Enter a valid nonnegative balance');break}let target=Math.round(Number(raw)*100),delta=target-balance(a);if(!Number.isSafeInteger(target)||!Number.isSafeInteger(a.opening+delta)){toast('Balance is too large');break}a.opening+=delta;persist();page='ledger';render();toast('Balance corrected');break}case'hide':prefs.hide=!prefs.hide;persistPrefs();render(true);break;case'start-empty':prefs.onboarded=true;data.accounts=[];data.transactions=[];persist();accountEditId=null;page='account-form';render();break;case'new-account':accountEditId=null;page='account-form';render();break;case'new-expense':case'ledger-expense':begin('Expense');break;case'ledger-income':begin('Income');break;case'ledger-transfer':begin('Transfer');break;case'prev-month':currentMonth=shiftMonth(currentMonth,-1);expanded=null;render(true);break;case'next-month':if(currentMonth<thisMonth())currentMonth=shiftMonth(currentMonth,1);expanded=null;render(true);break;case'cancel-editor':back();break;case'save-editor':commitEditor();break;case'swap':syncEditor();{let d=draft();[d.from,d.to]=[d.to,d.from];render(true)}break;case'batch':syncEditor();batch.push({description:'',digits:'',account:(origin==='ledger'?currentAccount:null)||prefs.defaultAccount||active()[0]?.id,date:draft().date});render(true);break;case'open-search':resetSearch();break;case'filters':searchFilters=!searchFilters;render(true);break;case'clear-filters':searchFilter={account:'',type:'',category:'',from:'',to:''};render(true);break;case'new-category':if(page==='editor')syncEditor();settingsReturn=page==='editor'?'editor':'settings';categoryId=null;page='category-form';render();break;case'save-category':saveCategory();break;case'delete-category':{let c=data.categories.find(z=>z.id===categoryId);if(!c||!confirm('Delete category? Existing transactions will become Uncategorized.'))break;data.categories=data.categories.filter(z=>z.id!==categoryId);data.transactions.forEach(t=>{if(t.category===categoryId)t.category=''});persist();page='settings';render();break}case'save-account':saveAccount();break;case'export':exportBackup();break;case'reset':if(confirm('Start fresh? This will erase all accounts and transactions on this device. Export a backup first if you need one.')){data.accounts=[];data.transactions=[];prefs.onboarded=false;prefs.defaultAccount='';prefs.openGroups=[];persist();page='wallet';render()}break;}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&page!=='wallet')back()});

// Keep Android Back inside the app until a second press on the wallet.
const BACK_GUARD='pesito-back-guard-v1';
function installBackGuard(){
 const standalone=window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone===true;
 const android=/Android/i.test(navigator.userAgent||'');
 if(!standalone&&!android)return;
 const guardState=()=>({...(history.state||{}),pesitoBackGuard:BACK_GUARD});
 // One same-URL guard entry protects the initial app document from an accidental Back.
 if(history.state?.pesitoBackGuard!==BACK_GUARD)history.pushState(guardState(),'');

 restoreExitGuard=()=>{
  if(!exitBackDeadline)return;
  exitBackDeadline=0;
  clearTimeout(toastTimer);
  el('#toast').style.display='none';
  if(history.state?.pesitoBackGuard!==BACK_GUARD)history.forward();
 };
 // Resuming app interaction cancels the pending exit before any navigation.
 document.addEventListener('pointerdown',restoreExitGuard,true);
 document.addEventListener('keydown',restoreExitGuard,true);
 window.addEventListener('popstate',e=>{
  if(document.querySelector('#plan-dialog[open]')){history.forward();closePlanDialog();return;}
  if(e.state?.pesitoBackGuard===BACK_GUARD)return;
  if(accountMenuOpen){history.forward();accountMenuOpen=false;render(true);return}
  if(page!=='wallet'){
   history.forward();
   if(page==='adjust-account'){page='ledger';render()}else back();
   return;
  }
  // Stay on the base document while the prompt is visible. The NEXT hardware
  // Back can now exit naturally, without traversing another synthetic entry.
  exitBackDeadline=Date.now()+2200;
  toast('Press again to exit');
  clearTimeout(toastTimer);
  toastTimer=setTimeout(restoreExitGuard,2200);
 });
 window.addEventListener('pageshow',e=>{
  if(e.persisted){
   clearTimeout(toastTimer);
   exitBackDeadline=0;
   el('#toast').style.display='none';
   if(history.state?.pesitoBackGuard!==BACK_GUARD)history.forward();
  }
 });
}

installBackGuard();
render();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));

